function onSearch() {
  gStatusText.removeAttribute("data-l10n-id");
  gStatusText.value = "";
  disableCommands();

  gSearchSession.clearScopes();

  var currentAbURI = document.getElementById("abPopup").getAttribute("value");

  gSearchSession.addDirectoryScopeTerm(GetScopeForDirectoryURI(currentAbURI));
  gSearchSession.searchTerms = saveSearchTerms(
    gSearchSession.searchTerms,
    gSearchSession
  );

  let searchUri = "?(";
  for (let i = 0; i < gSearchSession.searchTerms.length; i++) {
    const searchTerm = gSearchSession.searchTerms[i];
    if (!searchTerm.value.str) {
      continue;
    }
    // get the "and" / "or" value from the first term
    if (i == 0) {
      if (searchTerm.booleanAnd) {
        searchUri += "and";
      } else {
        searchUri += "or";
      }
    }

    var attrs;

    switch (searchTerm.attrib) {
      case Ci.nsMsgSearchAttrib.Name:
        attrs = [
          "DisplayName",
          "FirstName",
          "LastName",
          "NickName",
          "_AimScreenName",
        ];
        break;
      case Ci.nsMsgSearchAttrib.DisplayName:
        attrs = ["DisplayName"];
        break;
      case Ci.nsMsgSearchAttrib.Email:
        attrs = ["PrimaryEmail"];
        break;
      case Ci.nsMsgSearchAttrib.PhoneNumber:
        attrs = [
          "HomePhone",
          "WorkPhone",
          "FaxNumber",
          "PagerNumber",
          "CellularNumber",
        ];
        // Change this to "or" to match any of these attributes.
        // Can't currently do "and" and "or" searches at the same time but
        // if you're looking up a number likely it's a full match so
        // it's less bad to find something compared to finding too much.
        searchUri = searchUri.replace(/and$/, "or");
        break;
